/* Agency layer: client records own campaigns; campaign records own production state. */
const previousRoute=route;
window.removeEventListener('hashchange',previousRoute);
const AGENCY_KEY='astoria-agency-v2';
const baseScenes=sceneData.map(s=>({...s}));
const oldProduct=product, oldSiteHTML=siteHTML, oldAssetSVG=assetSVG, oldStoryboardHTML=storyboardHTML, oldManifest=manifest;
const campaignPages={overview,brief,direction,storyboard,assets,review,website,delivery};
const agencyPages=['agency','clients','intake','websites'];
const clientPages=['client','strategy','contacts'];
let intakeStep=0,searchTerm='',clientFilter='all';
const draftDefaults=()=>({name:'',industry:'',site:'',contactName:'',email:'',role:'Marketing lead',positioning:'',audience:'',voice:'',goal:'',headline:'',campaignName:'',due:'',budget:'',scope:'Campaign + storyboard + microsite',notes:'',files:[]});
function newCampaign(id,name,headline,client,approvals=false){const c=initial();Object.assign(c,{id,name,headline,version:1,directionApproved:approvals,due:'2026-11-06',owner:client.owner||'Agency producer',approverId:client.contacts[0]?.id||'',budget:'Discovery',site:{built:false,approved:false,version:1,headline},brief:{audience:client.strategy.audience,objective:client.goal,facts:`${client.name} is a fictional ${client.industry.toLowerCase()} brand. ${client.strategy.positioning} Only the supplied campaign facts are approved.`}});c.scenes.forEach(s=>s.approved=approvals);c.assets.forEach(s=>s.approved=approvals);c.activity=[{text:'Campaign workspace created',detail:name+' · fictional client'}];return c}
function seedAgency(){const clients=[
{id:'solune',name:'Solune',industry:'Skincare',initials:'S',color:'#dcd5eb',ink:'#51415f',status:'Active',owner:'Alex Lee',site:'solune.example',goal:'Introduce the Daily Moisturizer and collect launch interest.',strategy:{positioning:'A quieter approach to the daily skincare ritual.',audience:'Adults looking for a simple, intentional skincare routine.',voice:'Quiet, warm, editorial. Short sentences and room to breathe.',pillars:'Daily rituals\nConsidered design\nSmall moments',constraints:'No clinical claims, invented ingredients, or efficacy promises.',version:1},contacts:[{id:'solune-poc',name:'Maya Chen',email:'maya@solune.example',role:'Brand director',responsibility:'Primary contact & final approver'},{id:'solune-creative',name:'Theo Park',email:'theo@solune.example',role:'Creative lead',responsibility:'Creative feedback'}],campaigns:[]},
{id:'forma',name:'Forma',industry:'Architecture',initials:'F',color:'#e3e8d5',ink:'#47563f',status:'Active',owner:'Jamie Reed',site:'forma.example',goal:'Introduce a fictional design studio and invite project inquiries.',strategy:{positioning:'Architecture shaped around the way people live.',audience:'Homeowners planning a thoughtful residential project.',voice:'Precise, grounded, human. Describe spaces without grand claims.',pillars:'Human scale\nMaterials with character\nIntentional spaces',constraints:'No invented completed projects, awards, or client testimonials.',version:1},contacts:[{id:'forma-poc',name:'Elliot Ross',email:'elliot@forma.example',role:'Studio principal',responsibility:'Primary contact & final approver'}],campaigns:[]},
{id:'kinfolk',name:'Kinfolk Coffee',industry:'Food & beverage',initials:'K',color:'#efdac4',ink:'#764f36',status:'Onboarding',owner:'Sam Rivera',site:'kinfolk.example',goal:'Build interest in a fictional neighborhood coffee launch.',strategy:{positioning:'A neighborhood ritual, one cup at a time.',audience:'Local coffee lovers looking for a welcoming everyday stop.',voice:'Conversational, welcoming, tactile. Keep it simple.',pillars:'The neighborhood\nEveryday rituals\nGood company',constraints:'Do not invent sourcing certifications, opening dates, or locations.',version:1},contacts:[{id:'kinfolk-poc',name:'Noah Ellis',email:'noah@kinfolk.example',role:'Founder',responsibility:'Primary contact & final approver'}],campaigns:[]}
]; const legacy=state;legacy.id='solune-launch';legacy.name='Daily Ritual';legacy.due='2026-11-06';legacy.owner='Alex Lee';legacy.approverId='solune-poc';legacy.budget='$8,000–12,000 · demo';clients[0].campaigns=[legacy,newCampaign('solune-seasonal','Winter Ritual','A little room for winter.',clients[0])];clients[1].campaigns=[newCampaign('forma-launch','Spaces for living','Designed around your life.',clients[1])];clients[2].campaigns=[newCampaign('kinfolk-launch','Your neighborhood ritual','Good mornings start together.',clients[2])];return {schema:2,activeClientId:'solune',activeCampaignId:'solune-launch',clients,intakes:[{id:'intake-kinfolk',clientId:'kinfolk',name:'Kinfolk Coffee',contactName:'Noah Ellis',email:'noah@kinfolk.example',industry:'Food & beverage',goal:clients[2].goal,scope:'Campaign + storyboard + microsite',status:'Needs information',notes:'Opening date and reference imagery are still needed.',files:[],due:'',budget:'To confirm'}],draft:draftDefaults()}}
let agency;try{const saved=JSON.parse(localStorage.getItem(AGENCY_KEY));agency=saved?.schema===2&&saved.clients?.length?saved:seedAgency()}catch{agency=seedAgency()}
function currentClient(){return agency.clients.find(c=>c.id===agency.activeClientId)||agency.clients[0]}
function currentCampaign(){const c=currentClient();return c.campaigns.find(p=>p.id===agency.activeCampaignId)||c.campaigns[0]}
function contactFor(c,p){return c.contacts.find(x=>x.id===p.approverId)||c.contacts[0]}
function setContext(){const c=currentClient();state=currentCampaign();agency.activeClientId=c.id;agency.activeCampaignId=state.id;sceneData=c.id==='solune'?baseScenes.map(s=>({...s})):genericScenes(c);assetName=i=>`${i<3?'Campaign hero':'Brand spotlight'} · ${['Square','Portrait','Vertical'][i%3]}`;}
function genericScenes(c){return [{name:'Set the scene',duration:3,copy:c.strategy.positioning,notes:'Establish the brand atmosphere with a clean concept visual.',style:'linen'},{name:'The brand promise',duration:4,copy:()=>state.headline,notes:'Introduce the campaign headline. Keep the brand voice clear.',style:'product'},{name:'A closer look',duration:3,copy:c.name,notes:'Show a considered detail from the selected direction.',style:'detail'},{name:'The human moment',duration:4,copy:c.strategy.pillars.split('\n')[0],notes:'Connect the story to the audience. Use supplied facts only.',style:'shelf'},{name:'Bring it together',duration:3,copy:'A story worth sharing.',notes:'Return to the campaign identity with space for copy.',style:'product'},{name:'The invitation',duration:3,copy:c.id==='forma'?'Start a conversation.':'Stay in the loop.',notes:'Brand end card with a clear invitation.',style:'end'}]}
persist=function(){try{localStorage.setItem(AGENCY_KEY,JSON.stringify(agency));document.getElementById('save-label').textContent='Saved locally'}catch{document.getElementById('save-label').textContent='Session only'}};
function approvedCount(p){return p.scenes.filter(x=>x.approved).length+p.assets.filter(x=>x.approved).length}
function campaignStatus(p){return p.revisionPending?'Needs rebuild':p.site.approved&&p.site.version===p.version?'Ready for delivery':approvedCount(p)===12&&p.directionApproved?'Website next':'In production'}
function logo(c,size=''){return `<span class="client-logo ${size}" style="background:${esc(c.color)};color:${esc(c.ink)}">${esc(c.initials)}</span>`}
function selectClient(id,campaignId){if(productionBusy){toast('Wait for the production simulation to finish before switching clients.');return false}const c=agency.clients.find(c=>c.id===id);if(!c)return false;agency.activeClientId=id;agency.activeCampaignId=c.campaigns.some(p=>p.id===campaignId)?campaignId:c.campaigns[0].id;filter='all';mobile=false;setContext();persist();return true}
function rowsCampaigns(){return agency.clients.flatMap(c=>c.campaigns.map(p=>({c,p})))}
function completion(p){return Math.round(approvedCount(p)/12*100)}
function tableCampaigns(items){return `<div class="campaign-table"><div class="table-head"><span>Campaign / client</span><span>Owner & approver</span><span>Progress</span><span>Status</span></div>${items.map(({c,p})=>`<button class="campaign-table-row" data-agency="open-campaign" data-client="${c.id}" data-campaign="${p.id}"><span class="table-campaign">${logo(c)}<span><strong>${esc(p.name)}</strong><small>${esc(c.name)} · Due ${esc(p.due||'to confirm')}</small></span></span><span class="table-person"><strong>${esc(p.owner||c.owner)}</strong><small>${esc(contactFor(c,p)?.name||'Approver needed')}</small></span><span class="table-progress">${completion(p)}%<span class="progress-bar"><span style="display:block;height:100%;background:#a7b775;width:${completion(p)}%"></span></span></span><span class="badge ${p.revisionPending?'stale':p.site.approved?'approved':''}">${campaignStatus(p)} ↗</span></button>`).join('')}</div>`}
function agencyOverview(){const rows=rowsCampaigns(),pending=rows.reduce((n,{p})=>n+12-approvedCount(p),0);return heading('ASTORIA / AGENCY WORKSPACE','Many brands. One clear view.','Make room for every client’s story, without losing the thread.',`<button class="button" data-agency="new-intake">New client intake <span>＋</span></button>`)+`<section class="agency-hero"><div><span class="tag">YOUR CREATIVE OPERATING SPACE</span><h2>Different brands.<br>Distinct stories.</h2><p>Strategy, people, production, and delivery.<br>A shared process with room for individuality.</p><a class="button light" href="#clients">Explore your clients ↗</a></div><div class="orbital-brands">${agency.clients.slice(0,3).map((c,i)=>`<button class="brand-orbit orbit-${i}" data-agency="open-client" data-client="${c.id}" style="background:${c.color};color:${c.ink}">${esc(c.name)}<small>${esc(c.industry)}</small></button>`).join('')}<span class="orbit-caption">THE STORIES IN YOUR STUDIO</span></div></section><div class="stats"><div class="stat"><div class="stat-top"><span>Client brands</span><span>◎</span></div><div class="stat-value">${String(agency.clients.length).padStart(2,'0')}</div><div class="stat-foot">${agency.clients.filter(c=>c.status==='Active').length} active · ${agency.clients.filter(c=>c.status==='Onboarding').length} onboarding</div></div><div class="stat"><div class="stat-top"><span>Campaigns</span><span>✳</span></div><div class="stat-value">${String(rows.length).padStart(2,'0')}</div><div class="stat-foot">Each with its own production workspace</div></div><div class="stat"><div class="stat-top"><span>Awaiting review</span><span>◉</span></div><div class="stat-value">${pending}</div><div class="stat-foot">Scene and graphic approvals</div></div><div class="stat"><div class="stat-top"><span>Website previews</span><span>↗</span></div><div class="stat-value">${String(rows.filter(({p})=>p.site.built).length).padStart(2,'0')}</div><div class="stat-foot">${rows.filter(({p})=>p.site.approved).length} approved · exportable HTML</div></div></div><div class="section-title"><h2>Across the agency</h2><a href="#clients">Client directory ↗</a></div><div class="panel">${tableCampaigns(rows)}</div><div class="agency-bottom"><div class="panel"><div class="section-title"><h2>Intake needs attention</h2><a href="#intake">Open intake queue ↗</a></div>${agency.intakes.filter(i=>i.status!=='Accepted').slice(0,3).map(i=>`<div class="intake-mini"><div><strong>${esc(i.name)}</strong><p>${esc(i.notes||i.goal)}</p></div><span class="badge stale">${esc(i.status)}</span></div>`).join('')||'<p class="muted">Your intake queue is clear.</p>'}</div><div class="panel"><div class="eyebrow">THE ASTORIA WAY</div><h3 style="font:28px Georgia;margin:15px 0">A shared process.<br>A distinct voice.</h3><p class="muted">Brand strategy belongs to the client. Briefs, reviews, and deliverables belong to a campaign. Every website stays connected to its sources.</p></div></div>`}
function clientsView(){const list=agency.clients.filter(c=>(clientFilter==='all'||c.status.toLowerCase()===clientFilter)&&`${c.name} ${c.industry}`.toLowerCase().includes(searchTerm.toLowerCase()));return heading('AGENCY / CLIENT DIRECTORY','Know the brand. Know the people.','A dedicated home for every client relationship.',`<button class="button" data-agency="new-intake">Add a client ＋</button>`)+`<div class="directory-tools"><label class="search-label"><span>⌕</span><input id="client-search" type="search" placeholder="Search clients or industries" value="${esc(searchTerm)}" aria-label="Search clients"></label><div class="filter-row" style="margin:0">${['all','active','onboarding'].map(f=>`<button class="filter ${clientFilter===f?'active':''}" data-agency="client-filter" data-filter="${f}">${f==='all'?'All clients':f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div></div><div class="grid three" id="client-results">${list.map(c=>`<article class="card client-card"><div class="client-cover" style="background:${c.color};color:${c.ink}"><span class="eyebrow" style="color:inherit">${esc(c.industry)}</span><h2>${esc(c.name)}</h2><span class="client-identity">${esc(c.initials)}<span>✦</span></span></div><div class="card-content"><div class="card-meta"><span>${c.campaigns.length} CAMPAIGN${c.campaigns.length!==1?'S':''}</span><span class="badge ${c.status==='Active'?'approved':'stale'}">${esc(c.status)}</span></div><h3>${esc(c.strategy.positioning)}</h3><p>${esc(c.contacts[0]?.name||'No primary contact')} · ${esc(c.contacts[0]?.role||'Contact needed')}</p><div class="client-card-footer"><span>Lead: ${esc(c.owner)}</span><button class="button secondary" data-agency="open-client" data-client="${c.id}">Open client ↗</button></div></div></article>`).join('')||'<div class="empty">No clients match this search.</div>'}</div>`}
function clientView(){const c=currentClient();return heading('CLIENT / '+esc(c.industry).toUpperCase(),esc(c.name)+', in focus.','The relationship, the brand, and the work—all in one place.',`<button class="button" data-agency="new-campaign">New campaign ＋</button>`)+`<section class="client-profile-hero" style="background:${c.color};color:${c.ink}"><div><div class="eyebrow" style="color:inherit">BRAND POSITIONING · V${c.strategy.version}</div><h2>${esc(c.strategy.positioning)}</h2><p>${esc(c.strategy.voice)}</p></div>${logo(c,'large')}</section><div class="client-summary"><a class="panel summary-link" href="#strategy"><span class="eyebrow">BRAND STRATEGY</span><strong>A distinct point of view</strong><small>Audience, voice, pillars, and guardrails ↗</small></a><a class="panel summary-link" href="#contacts"><span class="eyebrow">PEOPLE & OWNERSHIP</span><strong>${c.contacts.length} point${c.contacts.length===1?'':'s'} of contact</strong><small>${esc(c.contacts[0]?.name||'Add a contact')} · lead: ${esc(c.owner)} ↗</small></a><a class="panel summary-link" href="#websites"><span class="eyebrow">WEBSITE REGISTRY</span><strong>${c.campaigns.filter(p=>p.site.built).length} campaign preview${c.campaigns.filter(p=>p.site.built).length===1?'':'s'}</strong><small>${esc(c.site||'Domain to confirm')} · demo domain ↗</small></a></div><div class="section-title"><h2>${esc(c.name)} campaigns</h2><span class="outline-label">CLIENT-SCOPED WORK</span></div><div class="panel">${tableCampaigns(c.campaigns.map(p=>({c,p})))}</div>`}
function strategyView(){const c=currentClient();return heading('CLIENT / BRAND STRATEGY','The story behind '+esc(c.name)+'.','A reusable foundation for every campaign this client creates.',`<button class="button" data-agency="save-strategy">Save strategy ✓</button>`)+`<div class="brief-layout"><div class="panel">${[['positioning','Brand positioning',false],['audience','Primary audience',true],['voice','Voice & tone',true],['pillars','Story pillars · one per line',true],['constraints','Creative guardrails',true]].map(([key,label,area])=>`<div class="field"><label for="strategy-${key}">${label}</label>${area?`<textarea id="strategy-${key}" maxlength="1200">${esc(c.strategy[key])}</textarea>`:`<input id="strategy-${key}" maxlength="220" value="${esc(c.strategy[key])}">`}</div>`).join('')}</div><div><div class="panel"><div class="eyebrow">BRAND DNA · V${c.strategy.version}</div><div class="swatches"><div class="swatch" style="background:${c.color}"></div><div class="swatch" style="background:${c.ink}"></div><div class="swatch" style="background:#f6f3eb"></div></div><p class="muted">This client’s color identity carries into their campaign previews and exportable website.</p><div class="field"><label for="strategy-color">Primary brand color</label><input id="strategy-color" type="color" value="${esc(c.color)}"></div><div class="field"><label for="strategy-ink">Text & accent color</label><input id="strategy-ink" type="color" value="${esc(c.ink)}"></div></div><div class="note" style="margin-top:18px">Saving a strategy change marks this client’s existing campaigns for rebuild and review. Other clients are unaffected.</div></div></div>`}
function contactsView(){const c=currentClient();return heading('CLIENT / CONTACTS','The people behind '+esc(c.name)+'.','Keep decision makers, day-to-day contacts, and agency ownership clear.',`<button class="button" data-agency="add-contact">Add contact ＋</button>`)+`<div class="preview-strip"><span>Agency lead: <strong>${esc(c.owner)}</strong> · ${esc(c.name)}</span><button class="text-button" data-agency="edit-owner">Edit owner ↗</button></div><div class="grid two">${c.contacts.map(contact=>`<article class="panel contact-card"><span class="avatar">${esc(contact.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><span class="eyebrow">${esc(contact.role)}</span><h3>${esc(contact.name)}</h3><p>${esc(contact.email)}</p><span class="badge ${contact.id===c.contacts[0].id?'approved':''}">${esc(contact.responsibility)}</span><div class="card-actions"><button class="text-button" data-agency="edit-contact" data-id="${contact.id}">Edit contact ↗</button></div></div></article>`).join('')}</div><div class="note" style="margin-top:20px">Contact addresses use reserved .example domains. This prototype records contacts and approvers locally; it sends no invitations or messages.</div><div class="panel"><div class="section-title"><h2>Campaign approvers</h2></div>${c.campaigns.map(p=>`<div class="approver-row"><label for="approver-${p.id}">${esc(p.name)}</label><select id="approver-${p.id}" data-approver="${p.id}" aria-label="Approver for ${esc(p.name)}">${c.contacts.map(x=>`<option value="${x.id}" ${p.approverId===x.id?'selected':''}>${esc(x.name)} · ${esc(x.role)}</option>`).join('')}</select></div>`).join('')}</div>`}
function intakeView(){return heading('AGENCY / DISCOVERY','Start with the right questions.','Capture the brand, the people, and the outcome before production starts.',`<button class="button" data-agency="new-intake">Start intake ＋</button>`)+`<div class="note">A four-step intake creates a client record, their strategy, primary contact, and first campaign. Drafts are saved in this browser as you type.</div><div class="panel"><div class="section-title"><h2>Intake queue</h2><span class="outline-label">${agency.intakes.length} REQUESTS</span></div>${agency.intakes.map(i=>`<div class="intake-row"><div><strong>${esc(i.name)}</strong><p>${esc(i.industry)} · ${esc(i.contactName)}</p><small>${esc(i.notes||i.goal)}</small></div><span class="badge ${i.status==='Accepted'?'approved':'stale'}">${esc(i.status)}</span><button class="button secondary" data-agency="view-intake" data-id="${i.id}">View intake ↗</button></div>`).join('')||'<p>No intake requests yet.</p>'}</div><div class="grid three" style="margin-top:20px">${[['01','Brand context','Positioning, audience, voice, and existing website.'],['02','People & scope','Primary contact, approver, deliverables, timing, and budget.'],['03','Ready for production','Review missing information and accept a brief with a clear outcome.']].map(x=>`<div class="panel"><div class="eyebrow">${x[0]} / DISCOVERY</div><h3>${x[1]}</h3><p class="muted">${x[2]}</p></div>`).join('')}</div>`}
function intakeDialog(){const d=agency.draft;const names=['The client','Brand strategy','Campaign scope','Review & create'];const field=(key,label,type='text',required=false)=>`<div class="field"><label for="intake-${key}">${label}${required?' *':''}</label>${type==='textarea'?`<textarea id="intake-${key}" data-draft="${key}" maxlength="1200">${esc(d[key])}</textarea>`:`<input id="intake-${key}" data-draft="${key}" type="${type}" ${type==='date'?'':'maxlength="300"'} value="${esc(d[key])}">`}</div>`;let body='';if(intakeStep===0)body=`<div class="grid two">${field('name','Client / brand name','text',true)}${field('industry','Industry','text',true)}</div>${field('site','Existing website or planned domain')}<div class="grid two">${field('contactName','Primary contact','text',true)}${field('email','Contact email','email',true)}</div>${field('role','Contact role')}`;if(intakeStep===1)body=field('positioning','What does the brand stand for?','textarea',true)+field('audience','Who should the story reach?','textarea',true)+field('voice','How should the brand sound?','textarea',true);if(intakeStep===2)body=field('campaignName','First campaign name','text',true)+field('headline','Working campaign headline','text',true)+field('goal','What outcome matters?','textarea',true)+`<div class="grid two">${field('due','Target delivery date','date')}${field('budget','Budget range')}</div><div class="field"><label for="intake-scope">Deliverables</label><select id="intake-scope" data-draft="scope">${['Campaign + storyboard + microsite','Campaign + static graphics','Storyboard + microsite'].map(s=>`<option ${d.scope===s?'selected':''}>${s}</option>`).join('')}</select></div>`+field('notes','References, constraints, or missing information','textarea')+`<div class="field"><label for="intake-files">Reference files · prototype filename record</label><input id="intake-files" type="file" multiple><small>${d.files.length?esc(d.files.join(', ')):'Files stay on your device. Only filenames are recorded; upload storage is not connected.'}</small></div>`;if(intakeStep===3)body=`<div class="intake-summary"><h3>${esc(d.name)}</h3><p>${esc(d.industry)} · ${esc(d.contactName)} (${esc(d.role)})<br>${esc(d.email)}</p><div class="delivery-check"><span>Positioning</span><strong>${esc(d.positioning)}</strong></div><div class="delivery-check"><span>Campaign</span><strong>${esc(d.campaignName)}</strong></div><div class="delivery-check"><span>Scope</span><strong>${esc(d.scope)}</strong></div><div class="delivery-check"><span>Timing / budget</span><strong>${esc(d.due||'To confirm')} / ${esc(d.budget||'To confirm')}</strong></div><p>${esc(d.goal)}</p></div><div class="note">Creates a local client record and campaign. Production is gated until this intake is accepted. No invitations, emails, or external uploads occur.</div>`;openDialog(`<div class="eyebrow">NEW CLIENT / STEP ${intakeStep+1} OF 4</div><h2 style="margin-top:10px">${names[intakeStep]}</h2><div class="intake-steps">${names.map((n,i)=>`<span class="${i===intakeStep?'active':i<intakeStep?'done':''}">${i<intakeStep?'✓':i+1} ${n}</span>`).join('')}</div><form id="intake-form" novalidate>${body}<div class="form-error" role="alert" id="intake-error"></div><div class="button-row">${intakeStep?'<button type="button" class="button secondary" data-agency="intake-back">← Back</button>':''}<button type="button" class="button" data-agency="${intakeStep===3?'intake-create':'intake-next'}">${intakeStep===3?'Create client workspace':'Continue'} →</button><button type="button" class="text-button" data-action="close">Save & close</button></div></form>`);}
function validateIntake(step){const d=agency.draft;const keys=[['name','industry','contactName','email'],['positioning','audience','voice'],['campaignName','headline','goal']][step]||[];if(keys.some(k=>!d[k].trim()))return 'Complete the required fields marked with an asterisk.';if(step===0&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email))return 'Enter a valid contact email.';if(step===0&&agency.clients.some(c=>c.name.toLowerCase()===d.name.trim().toLowerCase()))return 'This client already exists. Open their workspace to add a campaign.';return ''}
function uuid(prefix){return prefix+'-'+crypto.randomUUID()}
function createFromIntake(){for(let i=0;i<3;i++){const err=validateIntake(i);if(err){intakeStep=i;intakeDialog();document.getElementById('intake-error').textContent=err;return}}const d=agency.draft,id=uuid('client');const c={id,name:d.name.trim(),industry:d.industry.trim(),initials:d.name.trim()[0].toUpperCase(),color:'#ded7eb',ink:'#51415f',status:'Onboarding',owner:'Agency producer',site:d.site.trim(),goal:d.goal.trim(),strategy:{positioning:d.positioning.trim(),audience:d.audience.trim(),voice:d.voice.trim(),pillars:'Brand story\nAudience connection\nClear invitation',constraints:d.notes.trim()||'Use supplied facts only. No invented claims.',version:1},contacts:[{id:uuid('contact'),name:d.contactName.trim(),email:d.email.trim(),role:d.role.trim()||'Primary contact',responsibility:'Primary contact & final approver'}],campaigns:[]};const p=newCampaign(uuid('campaign'),d.campaignName.trim(),d.headline.trim(),c);p.due=d.due;p.budget=d.budget;p.scope=d.scope;c.campaigns=[p];agency.clients.push(c);agency.intakes.unshift({...d,id:uuid('intake'),clientId:id,status:'Ready for review',files:[...d.files]});agency.draft=draftDefaults();selectClient(id);dialog.close();location.hash='client';render();toast('Client created. Review and accept intake before production.');}
function websitesView(){const rows=rowsCampaigns();return heading('AGENCY / WEBSITE REGISTRY','Every brand, its own home.','Client-specific campaign previews, approvals, and standalone exports.')+`<div class="note">These are preview websites with demo domains. Actual client hosting, DNS, and public publication are not connected.</div><div class="grid three">${rows.map(({c,p})=>`<article class="card"><div class="website-cover" style="background:${c.color};color:${c.ink}"><div class="mini-browser"><span>● ● ●</span><small>${esc(c.site||'Domain to confirm')}</small></div><div class="mini-site"><div class="mini-wordmark">${esc(c.name)}</div><h3>${esc(p.headline)}</h3><div class="mini-rule"></div><span>THE CAMPAIGN STORY ↗</span></div></div><div class="card-content"><div class="card-meta"><span>${esc(c.name.toUpperCase())}</span><span class="badge ${p.site.approved?'approved':''}">${p.revisionPending&&p.site.built?'Needs rebuild':p.site.approved?'Approved':p.site.built?'In review':'Not built'}</span></div><h3>${esc(p.name)}</h3><p>${p.site.built?'Preview v'+p.site.version+' · campaign v'+p.version:'Approve campaign materials before assembly.'}</p><button class="button secondary" data-agency="open-website" data-client="${c.id}" data-campaign="${p.id}">${p.site.built?'Open website preview':'Open campaign website'} ↗</button></div></article>`).join('')}</div>`}
function campaignOverview(){const c=currentClient();return heading('CLIENT / '+esc(c.name).toUpperCase(),esc(state.name)+'.','A focused production workspace for '+esc(c.name)+'.',`<button class="button" data-action="go" data-target="review">Open review queue ↗</button>`)+revisionNote()+`<div class="campaign-context-strip"><span>Agency lead: <strong>${esc(state.owner||c.owner)}</strong></span><span>Approver: <strong>${esc(contactFor(c,state)?.name||'To confirm')}</strong></span><span>Due: <strong>${esc(state.due||'To confirm')}</strong></span><a href="#client">Client profile ↗</a></div><section class="hero" style="background:${c.color}"><div class="hero-copy"><span class="tag">${esc(c.name.toUpperCase())} · ${campaignStatus(state).toUpperCase()}</span><h2 style="color:${c.ink}">${esc(state.headline)}</h2><p>${esc(c.strategy.positioning)}</p><button class="button light" data-action="go" data-target="brief">Explore campaign brief ↗</button></div><div class="hero-art">${product('campaignhero')}<span class="art-caption">${esc(c.name.toUpperCase())} · ${esc(state.name.toUpperCase())}</span></div></section><div class="stats"><div class="stat"><div class="stat-top"><span>Brand strategy</span><span>✳</span></div><div class="stat-value">v${c.strategy.version}</div><div class="stat-foot">${esc(c.industry)} · ${state.directionApproved?'direction approved':'direction in review'}</div></div><div class="stat"><div class="stat-top"><span>Storyboard</span><span>▤</span></div><div class="stat-value">06 <small>scenes · 20 seconds</small></div><div class="stat-foot">${state.scenes.filter(s=>s.approved).length} approved</div></div><div class="stat"><div class="stat-top"><span>Campaign assets</span><span>▧</span></div><div class="stat-value">06 <small>graphics</small></div><div class="stat-foot">${state.assets.filter(a=>a.approved).length} approved</div></div><div class="stat"><div class="stat-top"><span>Review progress</span><span>◉</span></div><div class="stat-value">${completion(state)}<small>%</small></div><div class="progress-bar"><div style="width:${completion(state)}%"></div></div></div></div><div class="overview-bottom"><div class="panel"><div class="section-title"><h2>Your production path</h2><a href="#delivery">Delivery checklist ↗</a></div><div class="pipeline">${['Brief','Direction','Storyboard','Assets','Website','Delivery'].map((n,i)=>`<a class="pipeline-step ${i===0?'done':''}" href="#${['brief','direction','storyboard','assets','website','delivery'][i]}"><span class="circle">${i+1}</span>${n}</a>`).join('')}</div><div class="next-action"><div><strong>Keep the story moving.</strong><p>Review the current campaign and its deliverables.</p></div><a class="button secondary" href="#review">Open review →</a></div></div><div class="panel"><div class="section-title"><h2>Campaign activity</h2></div>${state.activity.slice(0,3).map(a=>`<div class="activity-row" style="margin-bottom:15px"><span class="activity-icon">✳</span><div><strong>${esc(a.text)}</strong><p>${esc(a.detail)}</p></div></div>`).join('')}</div></div>`}
function agencyCampaignBrief(){const c=currentClient();return heading('CAMPAIGN / BRIEF',esc(state.name)+': the starting point.','Campaign-specific requirements, grounded in '+esc(c.name)+'’s strategy.',`<button class="button" data-action="save-brief">Save brief ✓</button>`)+revisionNote()+`<div class="brief-layout"><div class="panel"><div class="field"><label for="headline">Approved campaign headline</label><input id="headline" maxlength="110" value="${esc(state.headline)}"><small>Headline changes invalidate dependent deliverable approvals.</small></div>${[['audience','Campaign audience'],['objective','Campaign objective'],['facts','Approved facts & claims']].map(([id,label])=>`<div class="field"><label for="${id}">${label}</label><textarea id="${id}" maxlength="1200">${esc(state.brief[id])}</textarea></div>`).join('')}<div class="grid two"><div class="field"><label for="campaign-due">Target delivery</label><input id="campaign-due" type="date" value="${esc(state.due||'')}"></div><div class="field"><label for="campaign-budget">Budget range</label><input id="campaign-budget" maxlength="150" value="${esc(state.budget||'')}"></div></div></div><div><div class="panel"><div class="eyebrow">${esc(c.name)} / BRAND STRATEGY V${c.strategy.version}</div><h3>${esc(c.strategy.positioning)}</h3><p class="muted">${esc(c.strategy.voice)}</p><div class="swatches"><div class="swatch" style="background:${c.color}"></div><div class="swatch" style="background:${c.ink}"></div></div><div class="note">${esc(c.strategy.constraints)}</div><a class="button secondary" href="#strategy">Open brand strategy ↗</a></div><div class="panel" style="margin-top:18px"><div class="eyebrow">OWNERSHIP & SCOPE</div><p class="muted">Agency lead: ${esc(state.owner||c.owner)}<br>Final approver: ${esc(contactFor(c,state)?.name||'To confirm')}<br>Requested scope: ${esc(state.scope||'Campaign + storyboard + microsite')}</p><p class="muted">Prototype production set: six scenes, six graphics, one website preview. Scope is recorded for discovery; output counts are fixed in this mockup.</p><a class="text-button" href="#contacts">Manage contacts & approvers ↗</a></div></div></div>`}
function agencyDirection(){const c=currentClient();return heading('CAMPAIGN / CREATIVE DIRECTION','A distinct voice for '+esc(c.name)+'.','Two illustrative approaches grounded in the client’s positioning.')+revisionNote()+`<div class="grid two">${[{id:'ritual',name:'The brand story',headline:state.headline,description:c.strategy.positioning},{id:'simple',name:'The audience connection',headline:c.strategy.pillars.split('\n')[0],description:'A direct, audience-led approach: '+c.strategy.audience}].map((d,i)=>`<article class="card"><div class="direction-cover ${i?'alt':''}" style="background:${i?'#efeee5':c.color};color:${c.ink}"><div class="eyebrow">CONCEPT 0${i+1}</div><h2 style="margin-top:18px">${esc(d.headline)}</h2>${product('clientdirection'+i)}</div><div class="card-content"><div class="card-meta"><span>STRATEGY V${c.strategy.version}</span><span class="badge ${state.direction===d.id&&state.directionApproved?'approved':''}">${state.direction===d.id?(state.directionApproved?'Selected & approved':'Selected · in review'):'Alternative'}</span></div><h3>${d.name}</h3><p>${esc(d.description)}</p><p>Voice: ${esc(c.strategy.voice)}</p><div class="button-row"><button class="button secondary" data-action="select-direction" data-id="${d.id}">${state.direction===d.id?'Selected direction ✓':'Select direction →'}</button>${state.direction===d.id&&!state.directionApproved?'<button class="button" data-action="approve-direction">Approve direction ✓</button>':''}</div></div></article>`).join('')}</div><p class="motion-note">These are strategy-informed concept mockups. Creative generation through MCP is not connected.</p>`}
campaignPages.brief=agencyCampaignBrief;
campaignPages.direction=agencyDirection;
function contextualHTML(html){const c=currentClient();if(c.id==='solune')return html;return html.replace(/Solune · Daily Ritual/g,esc(c.name)+' · '+esc(state.name)).replace(/Solune Daily Moisturizer/g,esc(c.name)+' · '+esc(state.name)).replace(/Solune/g,esc(c.name)).replace(/solune/g,esc(c.name.toLowerCase())).replace(/The Daily Ritual/g,'The Brand Story').replace(/The daily ritual/g,'The brand story').replace(/Daily Ritual/g,esc(state.name)).replace(/The Daily Ritual/g,esc(state.name)).replace(/Make room for your daily ritual\./g,esc(state.headline)).replace(/Less noise\. More you\./g,'A story worth sharing.').replace(/skincare/g,esc(c.industry.toLowerCase())).replace(/#ded6ef|#dcd4eb|#dcd5eb|#e8e9d5|#e7ddcf/g,c.color).replace(/#51415f/g,c.ink).replace(/Ritual hero/g,'Campaign hero').replace(/Product spotlight/g,'Brand spotlight').replace(/a 15–30-second video/g,'a campaign video').replace(/daily-ritual/g,esc(state.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')));}
function buildNavigation(){const c=currentClient();document.querySelector('.brand').href='#agency';document.querySelector('.workspace-label').textContent='THE AGENCY';document.getElementById('nav').innerHTML=`<a href="#agency" data-page="agency">◫ <span>Agency overview</span></a><a href="#clients" data-page="clients">◎ <span>Clients</span><b>${agency.clients.length}</b></a><a href="#intake" data-page="intake">☷ <span>Intake queue</span><b>${agency.intakes.filter(i=>i.status!=='Accepted').length}</b></a><a href="#websites" data-page="websites">↗ <span>Client websites</span></a><div class="nav-divider">CLIENT WORKSPACE</div><label class="client-switch-label" for="client-switch">Client</label><select id="client-switch" class="sidebar-select">${agency.clients.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><a href="#client" data-page="client">◈ <span>Client profile</span></a><a href="#strategy" data-page="strategy">✳ <span>Brand strategy</span></a><a href="#contacts" data-page="contacts">♧ <span>Contacts</span></a><div class="nav-divider">CAMPAIGN</div><label class="client-switch-label" for="campaign-switch">Campaign</label><select id="campaign-switch" class="sidebar-select">${c.campaigns.map(p=>`<option value="${p.id}" ${p.id===state.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>${[['overview','Campaign overview','◫'],['brief','Campaign brief','☷'],['direction','Creative direction','✳'],['storyboard','Storyboard','▤'],['assets','Asset library','▧'],['review','Review & approvals','◉'],['website','Campaign website','↗'],['delivery','Delivery','⇩']].map(([id,name,icon])=>`<a href="#${id}" data-page="${id}">${icon} <span>${name}</span>${id==='review'?`<b id="review-count">${12-approvedCount(state)}</b>`:''}</a>`).join('')}`;document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));document.querySelector('.breadcrumbs').innerHTML=`<span class="prototype-pill">DEMO</span><a href="#agency">Agency</a><span>/</span>${agencyPages.includes(page)?`<strong>${{agency:'Overview',clients:'Clients',intake:'Intake queue',websites:'Website registry'}[page]}</strong>`:`<a href="#client">${esc(c.name)}</a>${clientPages.includes(page)?'':`<span>/</span><strong>${esc(state.name)}</strong>`}`}`;document.querySelector('.workspace-footer>span').innerHTML=`ASTORIA <span>×</span> ${agencyPages.includes(page)?'BRAND STORIES':esc(c.name.toUpperCase())}`;}
render=function(){setContext();buildNavigation();const views={agency:agencyOverview,clients:clientsView,client:clientView,strategy:strategyView,contacts:contactsView,intake:intakeView,websites:websitesView};main.innerHTML=views[page]?views[page]():contextualHTML((page==='overview'?campaignOverview:campaignPages[page]||campaignOverview)());if(!agencyPages.includes(page)&&!clientPages.includes(page)&&!intakeAccepted(currentClient()))main.insertAdjacentHTML('afterbegin','<div class="note warning">Client onboarding is awaiting intake acceptance. You can plan and review, but production and website assembly are gated. <a href="#intake">Review intake →</a></div>');document.querySelectorAll('.hero-art').forEach(el=>el.dataset.brand=currentClient().name.toUpperCase());if(page==='website'&&state.site.built)document.getElementById('site-frame').srcdoc=siteHTML(state.site.headline);persist()};
route=function(){const target=location.hash.slice(1)||'agency';page=[...agencyPages,...clientPages,...Object.keys(campaignPages)].includes(target)?target:'agency';render();window.scrollTo(0,0)};
function intakeAccepted(c){const intake=agency.intakes.find(i=>i.clientId===c.id);return !intake||intake.status==='Accepted'}
product=function(id='p',color){const c=currentClient();if(c.id==='solune')return oldProduct(id,color);const architecture=c.id==='forma';return `<svg class="product-svg" viewBox="0 0 440 300" role="img" aria-label="${esc(c.name)} original concept illustration"><rect width="440" height="300" fill="${c.color}"/>${architecture?`<path d="M75 248V91L190 40L335 90V248Z" fill="#f4f0e4"/><path d="M190 40V248H335V90Z" fill="#c9d1b8"/><path d="M102 110L159 86V205H102Z" fill="#75846b"/><path d="M216 107H298V205H216Z" fill="#849372"/><path d="M75 248L190 273L373 249L335 224Z" fill="#b8c5a9"/>`:`<ellipse cx="239" cy="257" rx="104" ry="12" fill="${c.ink}" opacity=".15"/><path d="M166 100H314L299 239Q240 261 180 239Z" fill="#f7f0e5"/><path d="M161 95H319V113H161Z" fill="${c.ink}"/><ellipse cx="240" cy="95" rx="79" ry="12" fill="#a58c76"/><path d="M181 157H303L300 202H178Z" fill="${c.color}"/><text x="239" y="186" text-anchor="middle" font-family="Georgia" font-size="21" fill="${c.ink}">${esc(c.name)}</text>`}<text x="28" y="280" font-size="9" font-family="Arial" fill="${c.ink}" letter-spacing="2">${esc(c.name.toUpperCase())} · CONCEPT VISUAL</text></svg>`};
sceneVisual=function(i){const c=currentClient();if(c.id==='solune'){if(i===0)return `<svg viewBox="0 0 440 300" class="product-svg" role="img" aria-label="Morning light on linen"><rect width="440" height="300" fill="#e8dfd1"/><path d="M-10 20L330 300M60 -10L400 300M150 -10L480 280" stroke="#bcb39f" stroke-width="29" opacity=".3"/><text x="34" y="70" fill="#6f6457" font-family="Georgia" font-size="25">A quieter start.</text></svg>`;if(i!==5)return product('scene'+i)}else if(i!==5)return product('scene'+i);return `<svg viewBox="0 0 440 300" class="product-svg" role="img" aria-label="${esc(c.name)} campaign end card"><rect width="440" height="300" fill="${c.color}"/><text x="220" y="140" text-anchor="middle" font-family="Georgia" font-size="${c.name.length>10?35:59}" fill="${c.ink}">${esc(c.name)}</text><text x="220" y="185" text-anchor="middle" font-family="Arial" font-size="12" fill="${c.ink}">${esc(typeof sceneData[i].copy==='function'?sceneData[i].copy():sceneData[i].copy)}</text></svg>`};
siteHTML=function(headline){const c=currentClient();if(c.id==='solune')return oldSiteHTML(headline).replace(/Solune · The daily ritual/g,'Solune · '+esc(state.name));return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(c.name)} · ${esc(state.name)}</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f4ee;color:${c.ink};font:14px Arial}a{color:inherit;text-decoration:none}.demo{text-align:center;background:${c.color};padding:8px;font-size:9px;letter-spacing:1px}nav{padding:25px 7%;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #ddd}.logo{font:32px Georgia}.hero{display:grid;grid-template-columns:1fr 1fr;background:${c.color};min-height:480px}.copy{padding:70px 12%;align-self:center}.label{font-size:9px;letter-spacing:2px;text-transform:uppercase}h1{font:clamp(38px,5vw,65px)/1.05 Georgia;margin:25px 0}p{line-height:1.8}svg{width:100%;height:100%;max-height:450px}.art{display:grid;place-items:center;padding:25px}.button{display:inline-block;border:0;background:${c.ink};color:white;padding:15px 22px;font-size:11px;cursor:pointer}.story{padding:60px 8%;display:grid;grid-template-columns:1fr 1fr;gap:40px}h2{font:38px Georgia;margin:0 0 20px}.pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;padding:0 8% 50px}.pillar{border-top:1px solid #c8c7bd;padding:20px 0;font:23px Georgia}.signup{text-align:center;padding:65px 8%;background:${c.color}}footer{padding:25px 7%;font-size:9px;display:flex;justify-content:space-between}#response{min-height:25px;margin-top:15px;font-size:11px}small{display:block;margin:16px 0;font-size:10px}a:focus-visible,button:focus-visible{outline:3px solid ${c.ink};outline-offset:4px}@media(max-width:600px){.hero,.story{grid-template-columns:1fr}.copy{padding:45px 8% 15px}.art{height:300px}.pillars{grid-template-columns:1fr}.story{padding:40px 8%;gap:20px}h1{font-size:43px}.logo{font-size:25px}footer{gap:20px}}</style></head><body><div class="demo">FICTIONAL BRAND · CAMPAIGN CONCEPT</div><nav><span class="logo">${esc(c.name)}</span><a href="#story">Our story ↗</a></nav><section class="hero"><div class="copy"><span class="label">${esc(c.industry)} / ${esc(state.name)}</span><h1>${esc(headline)}</h1><p>${esc(c.strategy.positioning)}</p><a class="button" href="#invitation">${c.id==='forma'?'Start a conversation':'Stay in the loop'} ↗</a></div><div class="art">${product('clientsite')}</div></section><section class="story" id="story"><h2>A story shaped<br>around you.</h2><p>${esc(c.strategy.positioning)} This is an illustrative campaign for ${esc(c.name)}, a fictional ${esc(c.industry.toLowerCase())} brand. The concept connects a distinct point of view with an invitation to learn more.</p></section><section class="pillars">${c.strategy.pillars.split('\n').slice(0,3).map(p=>`<div class="pillar">${esc(p)}</div>`).join('')}</section><section class="signup" id="invitation"><h2>${esc(headline)}</h2><p>${esc(state.brief.objective)}</p><button class="button" id="join">${c.id==='forma'?'Start a conversation':'Stay in the loop'} ↗</button><small>Demo interaction · no data is collected</small><div id="response" role="status" aria-live="polite"></div></section><footer><span>${esc(c.name)}</span><span>Brand story created with Astoria · Fictional portfolio demo</span></footer><script>document.getElementById('join').onclick=function(){document.getElementById('response').textContent='Thanks for exploring this concept. No data was collected.';};<\/script></body></html>`};
assetSVG=function(i){return contextualHTML(oldAssetSVG(i)).replace(/#dcd4eb|#e8e9d5|#e7ddcf/g,currentClient().color).replace(/#51415f/g,currentClient().ink)};
storyboardHTML=function(){return contextualHTML(oldStoryboardHTML())};
manifest=function(){return {...oldManifest(),clientId:currentClient().id,client:currentClient().name,campaignId:state.id,campaign:state.name,brandStrategyVersion:currentClient().strategy.version,approver:contactFor(currentClient(),state)?.name,website:{...oldManifest().website,template:currentClient().id==='solune'?'solune-microsite-v1':'client-microsite-v1'}}};
const baseRegenerate=regenerate;
regenerate=async function(){if(!intakeAccepted(currentClient()))return toast('Accept this client’s intake before production.');await baseRegenerate()};
function contactDialog(contact){openDialog(`<h2>${contact?'Edit':'Add'} point of contact</h2><div class="field"><label for="contact-name">Name</label><input id="contact-name" maxlength="120" value="${esc(contact?.name||'')}"></div><div class="field"><label for="contact-email">Email</label><input id="contact-email" type="email" value="${esc(contact?.email||'')}"></div><div class="field"><label for="contact-role">Role</label><input id="contact-role" maxlength="120" value="${esc(contact?.role||'')}"></div><div class="field"><label for="contact-responsibility">Responsibility</label><select id="contact-responsibility">${['Primary contact & final approver','Creative feedback','Day-to-day contact','Final approver'].map(r=>`<option ${(contact?.responsibility||'Day-to-day contact')===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="form-error" id="contact-error" role="alert"></div><div class="button-row"><button class="button" data-agency="save-contact" data-id="${contact?.id||''}">Save contact</button><button class="button secondary" data-action="close">Cancel</button></div>`)}
function blockProduction(e){const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='save-brief'){e.stopImmediatePropagation();if(productionBusy)return toast('Finish the current job before changing its inputs.');const headline=document.getElementById('headline').value.trim(),next={audience:document.getElementById('audience').value.trim(),objective:document.getElementById('objective').value.trim(),facts:document.getElementById('facts').value.trim()};if(!headline||!Object.values(next).every(Boolean))return toast('Complete the headline and all brief fields.');const changedBrief=JSON.stringify(next)!==JSON.stringify(state.brief),changedHeadline=headline!==state.headline;state.brief=next;state.due=document.getElementById('campaign-due').value;state.budget=document.getElementById('campaign-budget').value.trim();if(changedHeadline)setHeadline(headline);if(changedBrief){if(!changedHeadline)state.version++;state.revisionPending=true;state.directionApproved=false;state.scenes.forEach(s=>{s.approved=false;s.version=state.version});state.assets.forEach(a=>{a.approved=false;a.version=state.version});state.site.approved=false;activity('Campaign brief revised','Audience, objective, or facts updated · rebuild and review required');}render();return toast(changedBrief||changedHeadline?'Brief saved. Rebuild and review affected creative.':'Brief saved locally.');}if(productionBusy&&['select-direction','save-brief','commit-revision'].includes(action)){e.stopImmediatePropagation();return toast('Finish the current production job before changing its inputs.')}if(action==='build-site'&&!intakeAccepted(currentClient())){e.stopImmediatePropagation();return toast('Accept intake before assembling a website.')}if(action==='download-site'||action==='download-asset'||action==='export-storyboard'||action==='download-bundle'||action==='fullscreen'){e.stopImmediatePropagation();const c=currentClient(),slug=c.name.toLowerCase().replace(/[^a-z0-9]+/g,'-'),prefix=slug+'-'+state.name.toLowerCase().replace(/[^a-z0-9]+/g,'-');if(action==='download-site'){if(!deliveryReady())return toast('Approve the current website before export.');download(prefix+'.html',siteHTML(state.site.headline),'text/html')}if(action==='download-asset'){const i=Number(b.dataset.index);download(prefix+'-asset-'+(i+1)+'.svg',assetSVG(i),'image/svg+xml')}if(action==='export-storyboard')download(prefix+'-storyboard.html',storyboardHTML(),'text/html');if(action==='download-bundle'){if(!deliveryReady())return toast('Complete current approvals before delivery.');const files=[{name:prefix+'.html',content:siteHTML(state.site.headline)},{name:'storyboard.html',content:storyboardHTML()},{name:'manifest.json',content:JSON.stringify(manifest(),null,2)},...state.assets.map((s,i)=>({name:`assets/${slug}-asset-${i+1}-v${s.version}.svg`,content:assetSVG(i)}))];download(prefix+'-v'+state.version+'.zip',zip(files),'application/zip');activity('Campaign bundle exported',c.name+' · v'+state.version);render()}if(action==='fullscreen'){openDialog('<h2>'+esc(c.name)+' · Campaign preview</h2><iframe id="dialog-frame" title="Expanded client website" sandbox="allow-scripts" style="height:65vh"></iframe><button class="button secondary" data-action="close" style="margin-top:15px">Close preview</button>');document.getElementById('dialog-frame').srcdoc=siteHTML(state.site.headline);return}toast('Client-specific deliverable downloaded.')}}
document.addEventListener('click',blockProduction,true);
document.addEventListener('input',e=>{if(e.target.dataset.draft){agency.draft[e.target.dataset.draft]=e.target.value;persist()}if(e.target.id==='client-search'){searchTerm=e.target.value;const pos=e.target.selectionStart;main.innerHTML=clientsView();const input=document.getElementById('client-search');input.focus();if(pos!==null)input.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.id==='client-switch'){if(selectClient(e.target.value)){location.hash='client';render()}else render()}if(e.target.id==='campaign-switch'){if(selectClient(currentClient().id,e.target.value)){location.hash='overview';render()}else render()}if(e.target.dataset.draft){agency.draft[e.target.dataset.draft]=e.target.value;persist()}if(e.target.id==='intake-files'){agency.draft.files=[...e.target.files].map(f=>f.name);persist();intakeDialog()}if(e.target.dataset.approver){const p=currentClient().campaigns.find(p=>p.id===e.target.dataset.approver);p.approverId=e.target.value;persist();toast('Campaign approver updated.')}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-agency]');if(!b||b.disabled)return;const action=b.dataset.agency,c=currentClient();if(productionBusy&&['save-strategy','intake-create','create-campaign','reset-agency'].includes(action))return toast('Finish the current job before changing its workspace.');
if(action==='open-client'){if(selectClient(b.dataset.client)){location.hash='client';render()}}
if(action==='open-campaign'||action==='open-website'){if(selectClient(b.dataset.client,b.dataset.campaign)){location.hash=action==='open-website'?'website':'overview';render()}}
if(action==='client-filter'){clientFilter=b.dataset.filter;render()}
if(action==='new-intake'){intakeStep=0;intakeDialog()}
if(action==='intake-back'){intakeStep--;intakeDialog()}
if(action==='intake-next'){const err=validateIntake(intakeStep);if(err){document.getElementById('intake-error').textContent=err;return}intakeStep++;intakeDialog()}
if(action==='intake-create')createFromIntake();
if(action==='save-strategy'){const next={...c.strategy};for(const key of ['positioning','audience','voice','pillars','constraints'])next[key]=document.getElementById('strategy-'+key).value.trim();if(Object.values(next).some(x=>typeof x==='string'&&!x))return toast('Complete all strategy fields.');const color=document.getElementById('strategy-color').value,ink=document.getElementById('strategy-ink').value;if(JSON.stringify(next)===JSON.stringify(c.strategy)&&color===c.color&&ink===c.ink)return toast('Strategy is unchanged.');next.version++;c.strategy=next;c.color=color;c.ink=ink;c.campaigns.forEach(p=>{p.version++;p.revisionPending=true;p.directionApproved=false;p.scenes.forEach(x=>{x.approved=false;x.version=p.version});p.assets.forEach(x=>{x.approved=false;x.version=p.version});p.site.approved=false;p.activity.unshift({text:'Client strategy revised',detail:'Brand strategy v'+next.version+' · rebuild required'})});render();toast('Strategy saved. This client’s campaigns need rebuild and review.');}
if(action==='add-contact')contactDialog();
if(action==='edit-contact')contactDialog(c.contacts.find(x=>x.id===b.dataset.id));
if(action==='save-contact'){const name=document.getElementById('contact-name').value.trim(),email=document.getElementById('contact-email').value.trim(),role=document.getElementById('contact-role').value.trim(),responsibility=document.getElementById('contact-responsibility').value;if(!name||!role||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){document.getElementById('contact-error').textContent='Enter a name, role, and valid email.';return}const contact=c.contacts.find(x=>x.id===b.dataset.id);if(contact)Object.assign(contact,{name,email,role,responsibility});else c.contacts.push({id:uuid('contact'),name,email,role,responsibility});dialog.close();render();toast('Contact saved to '+c.name+'.');}
if(action==='edit-owner')openDialog(`<h2>Agency ownership</h2><div class="field"><label for="agency-owner">Agency lead for ${esc(c.name)}</label><input id="agency-owner" maxlength="120" value="${esc(c.owner)}"></div><button class="button" data-agency="save-owner">Save owner</button>`);
if(action==='save-owner'){const owner=document.getElementById('agency-owner').value.trim();if(!owner)return toast('Enter an owner name.');c.owner=owner;c.campaigns.forEach(p=>p.owner=owner);dialog.close();render();toast('Agency lead updated.');}
if(action==='new-campaign')openDialog(`<h2>A new story for ${esc(c.name)}.</h2><div class="field"><label for="new-campaign-name">Campaign name</label><input id="new-campaign-name" maxlength="120"></div><div class="field"><label for="new-campaign-headline">Working headline</label><input id="new-campaign-headline" maxlength="110"></div><div class="field"><label for="new-campaign-goal">Campaign objective</label><textarea id="new-campaign-goal" maxlength="800">${esc(c.goal)}</textarea></div><div class="field"><label for="new-campaign-due">Target delivery</label><input id="new-campaign-due" type="date"></div><button class="button" data-agency="create-campaign">Create campaign →</button>`);
if(action==='create-campaign'){const name=document.getElementById('new-campaign-name').value.trim(),headline=document.getElementById('new-campaign-headline').value.trim(),goal=document.getElementById('new-campaign-goal').value.trim();if(!name||!headline||!goal)return toast('Enter a campaign name, headline, and objective.');const p=newCampaign(uuid('campaign'),name,headline,c);p.owner=c.owner;p.brief.objective=goal;p.due=document.getElementById('new-campaign-due').value;c.campaigns.push(p);selectClient(c.id,p.id);dialog.close();location.hash='overview';render();toast('Campaign created with this client’s brand strategy.');}
if(action==='view-intake'){const i=agency.intakes.find(i=>i.id===b.dataset.id);openDialog(`<div class="eyebrow">CLIENT INTAKE</div><h2>${esc(i.name)}</h2><p>${esc(i.industry)} · ${esc(i.contactName)}<br>${esc(i.email)}</p><div class="delivery-check"><span>Scope</span><strong>${esc(i.scope)}</strong></div><div class="delivery-check"><span>Target date</span><strong>${esc(i.due||'To confirm')}</strong></div><div class="delivery-check"><span>Budget</span><strong>${esc(i.budget||'To confirm')}</strong></div><p>${esc(i.goal)}</p><div class="field"><label for="intake-review-notes">Discovery notes / missing information</label><textarea id="intake-review-notes" maxlength="1500">${esc(i.notes||'')}</textarea></div><div class="button-row"><button class="button" data-agency="accept-intake" data-id="${i.id}" ${i.status==='Accepted'?'disabled':''}>${i.status==='Accepted'?'Accepted ✓':'Accept intake'}</button><button class="button secondary" data-agency="needs-info" data-id="${i.id}">Save as needs information</button><button class="text-button" data-action="close">Close</button></div>`)}
if(action==='accept-intake'||action==='needs-info'){const i=agency.intakes.find(i=>i.id===b.dataset.id);i.notes=document.getElementById('intake-review-notes').value.trim();i.status=action==='accept-intake'?'Accepted':'Needs information';const client=agency.clients.find(c=>c.id===i.clientId);if(client)client.status=action==='accept-intake'?'Active':'Onboarding';dialog.close();render();toast(action==='accept-intake'?'Intake accepted. Production is ready.':'Intake marked as needing information.');}
});
document.getElementById('reset').onclick=()=>openDialog('<h2>Reset the agency demo?</h2><p>This restores the three example clients and clears locally created clients, campaigns, contacts, and intake drafts.</p><div class="button-row"><button class="button" data-agency="reset-agency">Reset agency demo</button><button class="button secondary" data-action="close">Keep working</button></div>');
document.addEventListener('click',e=>{if(e.target.closest('[data-agency="reset-agency"]')){if(productionBusy)return toast('Finish the current job before resetting.');state=initial();agency=seedAgency();setContext();dialog.close();location.hash='agency';render();toast('Agency demo restored.')}});
document.getElementById('help').onclick=()=>openDialog('<h2>Astoria. Every brand has a story.</h2><p>Start at the agency overview, open a client, and explore their strategy, contacts, campaigns, and website previews. Use the four-step intake to add a client and review the request before production.</p><p>This is a browser-local prototype. Clients are fictional; there are no production accounts, live MCP jobs, emails, shared storage, or live client domains. Contact records do not grant access.</p><button class="button" data-action="close">Back to Astoria →</button>');
window.addEventListener('hashchange',route);
setContext();route();
